+const IF_TAG = /^#if(?=\s|$)\s*([\s\S]*)$/;
+
 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(pos) });
+      break;
+    }
+    if (open > pos) {
+      tokens.push({ kind: "text", text: template.slice(pos, open) });
+    }
+
+    const raw = template.startsWith("{{{", open);
+    const closer = raw ? "}}}" : "}}";
+    const start = open + (raw ? 3 : 2);
+    const close = template.indexOf(closer, start);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+    pos = close + closer.length;
+
+    const content = template.slice(start, close).trim();
+    if (raw) {
+      tokens.push({ kind: "value", expr: content, raw: true });
+      continue;
+    }
+
+    const ifMatch = IF_TAG.exec(content);
+    if (ifMatch) {
+      tokens.push({ kind: "if", path: ifMatch[1].trim() });
+    } else if (content === "else") {
+      tokens.push({ kind: "else" });
+    } else if (content === "/if") {
+      tokens.push({ kind: "end" });
+    } else {
+      tokens.push({ kind: "value", expr: content, raw: false });
+    }
+  }
+
+  return tokens;
